mapper.select:
/* Park.Seoung.Won */ /* 안정도 관찰지 목록 조회 - selectDeofstObservList */
T.CASE_MNG_NO AS CASE_MNG_NO /* 사례관리번호 */ , T.CASE_MNG_ODRNO AS CASE_MNG_ODRNO /* 사례관리차수 */ , T.WRT_YMD AS WRT_YMD /* 작성일자 */ , T.TKCG_RELM_SE_CD AS TKCG_RELM_SE_CD /* 영역구분코드 */ , DEC_B64(NVL(T3.FLNM_ENCPT, T2.TRPR_NM_ENCPT)) AS TRPR_NM /* 대상자명암호화 */ , T2.TRPR_BRTH_YMD AS TRPR_BRTH_YMD /* 대상자출생일자 */ , NVL(T3.SXDC_SE_CD, T2.SXDC_SE_CD) AS SXDC_SE_CD /* 대상자성별구분코드 */ , T1.YNGBGS_SE_NO AS YNGBGS_SE_NO /* 청소년구분번호 */ , DEC_B64(T5.FLNM_ENCPT) AS PIC_FLNM /* 담당자명암호화 */ , T6.INST_NM AS INST_NM /* 담당기관명 */ , T2.CASE_TRPR_TYPE_SE_CD AS CASE_TRPR_TYPE_SE_CD /* 사례대상자유형구분코드 */ , T1.CASE_PRGRS_STTS_SE_CD AS CASE_PRGRS_STTS_SE_CD /* 사례진행상태구분코드 */ , (SELECT DEC_B64(FLNM_ENCPT) FROM SCA100 WHERE ENFSN_NO = T.PIC_NO ) AS WRT_NM /* 작성자명 */ , T.DEOFST_LEVEL_DGREE_CNT1 + /* 1번문항 */ T.DEOFST_LEVEL_DGREE_CNT2 + /* 2번문항 */ T.DEOFST_LEVEL_DGREE_CNT3 + /* 3번문항 */ T.DEOFST_LEVEL_DGREE_CNT4 + /* 4번문항 */ T.DEOFST_LEVEL_DGREE_CNT5 + /* 5번문항 */ T.DEOFST_LEVEL_DGREE_CNT6 + /* 6번문항 */ T.DEOFST_LEVEL_DGREE_CNT7 + /* 7번문항 */ T.DEOFST_LEVEL_DGREE_CNT8 + /* 8번문항 */ T.DEOFST_LEVEL_DGREE_CNT9 + /* 9번문항 */ T.DEOFST_LEVEL_DGREE_CNT10 /* 10번문항 */ AS TOTAL /* 안정도관찰지합계 */ , T10.BIZ_YR AS BIZ_YR /* 사업연도 */ , T9.SRVC_EXCN_BIZ_NO AS SRVC_EXCN_BIZ_NO /* 서비스실행사업번호 */ , T1.CASE_BGNG_YMD AS CASE_BGNG_YMD /* 사례시작일자 */ , T1.CASE_TRMN_YMD AS CASE_TRMN_YMD /* 사례종결일자 */ , T11.TRMN_SE_CD AS TRMN_SE_CD /* 종결구분코드 */ , T11.TRMN_CS_SE_CD AS TRMN_CS_SE_CD /* 종결사유구분코드 */
FROM AFA280 T LEFT JOIN SEB100 T1 ON (T1.CASE_MNG_NO,T1.CASE_MNG_ODRNO) = (T.CASE_MNG_NO,T.CASE_MNG_ODRNO) JOIN SEA200 T2 ON T1.TRPR_INFO_NO = T2.TRPR_INFO_NO LEFT JOIN SCA300 T3 ON T2.INDV_IDNTFC_NO = T3.INDV_IDNTFC_NO LEFT JOIN SEB150 T4 ON T1.CASE_MNG_NO = T4.CASE_MNG_NO AND T1.CASE_MNG_ODRNO = T4.CASE_MNG_ODRNO LEFT JOIN SCA100 T5 ON T4.CASE_PIC_NO = T5.ENFSN_NO LEFT JOIN SAA000 T6 ON T4.PIC_INST_NO = T6.INST_NO LEFT JOIN SEB120 T8 ON T1.CASE_MNG_NO = T8.CASE_MNG_NO AND T1.CASE_MNG_ODRNO = T8.CASE_MNG_ODRNO INNER JOIN SDA420 T9 ON T8.SRVC_EXCN_BIZ_NO = T9.SRVC_EXCN_BIZ_NO LEFT JOIN SDA400 T10 ON T9.SRVC_BIZ_NO = T10.SRVC_BIZ_NO LEFT JOIN (SELECT B.* ,ROW_NUMBER() OVER(PARTITION BY B.CASE_MNG_NO, B.CASE_MNG_ODRNO ORDER BY B.CASE_TRMN_NO DESC) AS RN FROM SEC100 A LEFT JOIN SEC100 B ON B.CASE_MNG_NO = A.CASE_MNG_NO AND B.CASE_MNG_NO = A.CASE_MNG_NO AND B.TRMN_SRNG_RESULT_SE_CD = '01' WHERE A.TRMN_SRNG_RESULT_SE_CD = '02' )T11 /* 사례종결 */ ON T11.CASE_MNG_NO = T1.CASE_MNG_NO AND T11.CASE_MNG_ODRNO = T1.CASE_MNG_ODRNO AND T11.RN=1
WHERE 1=1 AND T8.DEL_YN = 'N' AND T4.PCHPRS_YN = 'Y' AND T1.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD} AND T.WRT_YMD BETWEEN #{START_DATE} AND #{END_DATE} /* 사업연도 */ AND T10.BIZ_YR = #{BIZ_YR} AND (T9.INST_NO = #{INST_NO} OR #{INST_TYPE_SE_CD} IN ('1'))
/* 청소년구분 */ AND T1.YNGBGS_SE_NO LIKE '%' || #{YNGBGS_STTS_LCLAS_SE_CD} || '%'
/* 사례진행상태구분코드 */ AND T1.CASE_PRGRS_STTS_SE_CD LIKE #{CASE_PRGRS_STTS_SE_CD} || '%'
/* 사례대상자유형구분코드 */ AND T2.CASE_TRPR_TYPE_SE_CD LIKE #{CASE_TRPR_TYPE_SE_CD} || '%'
/* 대상자성명 */ AND NVL(T3.FLNM_ENCPT, T2.TRPR_NM_ENCPT) = ENC_B64(#{TRPR_NM})
/* 담당자성명 */ AND T5.FLNM_ENCPT = ENC_B64(#{PIC_FLNM})
/* 서비스실행사업번호 */ AND T9.SRVC_EXCN_BIZ_NO LIKE #{SRVC_EXCN_BIZ_NO} || '%'
/* 종결구분코드 */ AND T11.TRMN_SE_CD LIKE #{TRMN_SE_CD} || '%'
/* 배정그룹소분류구분코드 */ AND T1.ALTMNT_GROUP_SCLAS_SE_CD = #{ALTMNT_GROUP_SCLAS_SE_CD}
/* 사례대상자번호 */ AND T1.CASE_MNG_NO LIKE '%' || #{CASE_MNG_NO} || '%' AND T1.CASE_MNG_ODRNO LIKE '%' || #{CASE_MNG_ODRNO} || '%'
/* 영역구분코드 */ AND T.TKCG_RELM_SE_CD = #{TKCG_RELM_SE_CD}
ORDER BY WRT_YMD DESC, CASE_MNG_NO, CASE_MNG_ODRNO


