/* Park.Seong.Won */
/* 안정도관찰지 수정 */

UPDATE AFA280 SET
    DEOFST_LEVEL_DGREE_CNT1 = #{DEOFST_LEVEL_DGREE_CNT1},       /* 안정도수준정도 1 */
    DEOFST_LEVEL_DGREE_CNT2 = #{DEOFST_LEVEL_DGREE_CNT2},       /* 안정도수준정도 2 */
    DEOFST_LEVEL_DGREE_CNT3 = #{DEOFST_LEVEL_DGREE_CNT3},       /* 안정도수준정도 3 */
    DEOFST_LEVEL_DGREE_CNT4 = #{DEOFST_LEVEL_DGREE_CNT4},       /* 안정도수준정도 4 */
    DEOFST_LEVEL_DGREE_CNT5 = #{DEOFST_LEVEL_DGREE_CNT5},       /* 안정도수준정도 5 */
    DEOFST_LEVEL_DGREE_CNT6 = #{DEOFST_LEVEL_DGREE_CNT6},       /* 안정도수준정도 6 */
    DEOFST_LEVEL_DGREE_CNT7 = #{DEOFST_LEVEL_DGREE_CNT7},       /* 안정도수준정도 7 */
    DEOFST_LEVEL_DGREE_CNT8 = #{DEOFST_LEVEL_DGREE_CNT8},       /* 안정도수준정도 8 */
    DEOFST_LEVEL_DGREE_CNT9 = #{DEOFST_LEVEL_DGREE_CNT9},       /* 안정도수준정도 9 */
    DEOFST_LEVEL_DGREE_CNT10 = #{DEOFST_LEVEL_DGREE_CNT10},     /* 안정도수준정도 10 */
    LAST_MDFR_ID = #{LAST_MDFR_ID},
    LAST_MDFCN_DT = SYSDATE
WHERE 1=1
AND CASE_MNG_NO = #{CASE_MNG_NO__origin}
AND CASE_MNG_ODRNO = #{CASE_MNG_ODRNO__origin}
AND WRT_YMD = #{WRT_YMD__origin}
AND TKCG_RELM_SE_CD = #{TKCG_RELM_SE_CD__origin}

mapper.select:
/* Park.Seoung.Won */ /* 문제행동발생보고서 목록 */ T1.CASE_MNG_NO AS CASE_MNG_NO /* 사례관리번호 */ , T1.CASE_MNG_ODRNO AS CASE_MNG_ODRNO /* 사례관리차수 */ , T1.WRT_YMD AS WRT_YMD /* 작성일자 */ , T1.INCDNT_ACDNT_CL_SE_CD AS INCDNT_ACDNT_CL_SE_CD /* 사건사고분류코드 */ , T1.OCRN_DT AS OCRN_DT /* 발생일시 */ , T1.INCDNT_ACDNT_CL_ETC_NM AS INCDNT_ACDNT_CL_ETC_NM /* 사건사고분류기타명 */ , T1.PLACE_NM AS PLACE_NM /* 장소명 */ , T1.PROBM_CN_PRTCLR_MATTER_NM AS PROBM_CN_PRTCLR_MATTER_NM /* 문제내용특이사항명 */ , T1.PIC_NO AS PIC_NO /* 보고자번호 */ , T1.MNGR_IDNTY_YN AS MNGR_IDNTY_YN /* 관리자확인여부 */ , T1.MNG_SN AS MNG_SN /* 관리일련번호 */ , CASE WHEN T1.SITTN_CN IS NULL OR T1.SITTN_CN = ' ' AND T1.ACTN_MATTER_DTL_CN IS NULL OR T1.ACTN_MATTER_DTL_CN = ' ' AND T1.ETC_MATTER_CN IS NULL OR T1.ETC_MATTER_CN = ' ' THEN 'X' ELSE 'O' END AS SITTN_CN_YN /* 상세내용여부 */ , T2.YNGBGS_SE_NO AS YNGBGS_SE_NO /* 청소년구분번호 */ , T2.CASE_PRGRS_STTS_SE_CD AS CASE_PRGRS_STTS_SE_CD /* 사례진행상태구분코드 */ , T2.ALTMNT_GROUP_SCLAS_SE_CD AS ALTMNT_GROUP_SCLAS_SE_CD /* 배정그룹구분코드 */ , T2.CASE_BGNG_YMD AS CASE_BGNG_YMD /* 사례시작일자 */ , T2.CASE_TRMN_YMD AS CASE_TRMN_YMD /* 사례종결일자 */ , ( SELECT UP_CMMNS_CD_VALUE FROM SAC100 WHERE CMMNS_CD_ID = 'CASE_PRGRS_STTS_SE_CD' AND CMMNS_CD_VALUE = T2.CASE_PRGRS_STTS_SE_CD ) AS CASE_PRGRS_STTS_TYPE_SE_CD /* 사례진행상태유형구분코드 */ , T2.TRPR_INFO_NO AS TRPR_INFO_NO /* 대상자정보번호 */ , T3.CASE_TRPR_TYPE_SE_CD AS CASE_TRPR_TYPE_SE_CD /* 사례대상자유형구분코드 */ , DEC_B64(NVL(T4.FLNM_ENCPT, T3.TRPR_NM_ENCPT)) AS TRPR_NM /* 대상자명 */ , TO_CHAR(TO_DATE(T3.TRPR_BRTH_YMD), 'YYYY-MM-DD') AS TRPR_BRTH_YMD /* 대상자출생일자 */ , NVL(T6.SXDC_SE_CD, T3.SXDC_SE_CD) AS SXDC_SE_CD /* 대상자성별구분코드 */ , DEC_B64(T6.FLNM_ENCPT) AS FLNM_NM /* 담당자명 */ , ( SELECT DEC_B64(FLNM_ENCPT) FROM SCA100 WHERE ENFSN_NO = T1.PIC_NO ) AS WRT_NM /* 보고자명 */ , T1.TKCG_INST_NO AS INST_NO /* 기관번호 */ , T7.INST_NM AS INST_NM /* 기관명 */ , T9.SRVC_EXCN_BIZ_NO AS SRVC_EXCN_BIZ_NO /* 서비스실행사업명 */ , T10.BIZ_YR AS BIZ_YR /* 사업연도 */ , T11.TRMN_SE_CD AS TRMN_SE_CD /* 종결구분코드 */ , T11.TRMN_CS_SE_CD AS TRMN_CS_SE_CD /* 종결사유구분코드 */
FROM AFA270 T1 LEFT JOIN SEB100 T2 ON T2.CASE_MNG_NO = T1.CASE_MNG_NO AND T2.CASE_MNG_ODRNO = T1.CASE_MNG_ODRNO JOIN SEA200 T3 ON T3.TRPR_INFO_NO = T2.TRPR_INFO_NO LEFT JOIN SCA300 T4 ON T3.INDV_IDNTFC_NO = T4.INDV_IDNTFC_NO LEFT JOIN (SELECT B.* ,ROW_NUMBER() OVER(PARTITION BY B.CASE_MNG_NO, B.CASE_MNG_ODRNO ORDER BY B.CASE_TRMN_NO DESC) AS RN FROM SEC100 A LEFT JOIN SEC100 B ON B.CASE_MNG_NO = A.CASE_MNG_NO AND B.CASE_MNG_NO = A.CASE_MNG_NO AND B.TRMN_SRNG_RESULT_SE_CD = '01' WHERE A.TRMN_SRNG_RESULT_SE_CD = '02' )T11 /* 사례종결 */ ON T11.CASE_MNG_NO = T1.CASE_MNG_NO AND T11.CASE_MNG_ODRNO = T1.CASE_MNG_ODRNO AND T11.RN=1 LEFT JOIN SEB150 T5 ON T1.CASE_MNG_NO = T5.CASE_MNG_NO AND T1.CASE_MNG_ODRNO = T5.CASE_MNG_ODRNO AND T5.PCHPRS_YN = 'Y' LEFT JOIN SCA100 T6 ON T5.CASE_PIC_NO = T6.ENFSN_NO LEFT JOIN SAA000 T7 ON T5.PIC_INST_NO = T7.INST_NO LEFT JOIN SEB120 T8 ON T1.CASE_MNG_NO = T8.CASE_MNG_NO AND T1.CASE_MNG_ODRNO = T8.CASE_MNG_ODRNO AND T8.DEL_YN != 'Y' INNER JOIN SDA420 T9 ON T8.SRVC_EXCN_BIZ_NO = T9.SRVC_EXCN_BIZ_NO LEFT JOIN SDA400 T10 ON T9.SRVC_BIZ_NO = T10.SRVC_BIZ_NO WHERE 1=1 AND T2.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD} AND (T9.INST_NO = #{INST_NO} OR #{INST_TYPE_SE_CD} IN ('1')) AND T1.WRT_YMD BETWEEN #{START_YMD} AND #{END_YMD} /* 사업연도 */ AND T10.BIZ_YR = #{BIZ_YR}
/* 청소년구분 */ AND T2.YNGBGS_SE_NO LIKE '%' || #{YNGBGS_STTS_LCLAS_SE_CD} || '%'
/* 사례진행상태구분코드 */ AND T2.CASE_PRGRS_STTS_SE_CD LIKE #{CASE_PRGRS_STTS_SE_CD} || '%'
/* 사례대상자유형구분코드 */ AND T3.CASE_TRPR_TYPE_SE_CD LIKE #{CASE_TRPR_TYPE_SE_CD} || '%'
/* 대상자성명 */ AND NVL(T4.FLNM_ENCPT, T3.TRPR_NM_ENCPT) = ENC_B64(#{TRPR_NM})
/* 담당자성명 */ AND T6.FLNM_ENCPT = ENC_B64(#{FLNM_NM})
/* 서비스실행사업번호 */ AND T9.SRVC_EXCN_BIZ_NO LIKE #{SRVC_EXCN_BIZ_NO} || '%'
/* 종결구분코드 */ AND T11.TRMN_SE_CD LIKE #{TRMN_SE_CD} || '%'
/* 배정그룹소분류구분코드 */ AND T2.ALTMNT_GROUP_SCLAS_SE_CD = #{ALTMNT_GROUP_SCLAS_SE_CD}
/* 사례대상자번호 */ AND T1.CASE_MNG_NO LIKE '%' || #{CASE_MNG_NO} || '%' AND T1.CASE_MNG_ODRNO LIKE '%' || #{CASE_MNG_ODRNO} || '%'
/* 관리자확인여부 */ AND T1.MNGR_IDNTY_YN LIKE #{MNGR_IDNTY_YN} || '%'
ORDER BY T1.OCRN_DT DESC, CASE_MNG_NO, CASE_MNG_ODRNO

	/* Park.Seoung.Won */
	/* 문제행동발생보고서 확인 */

    SELECT COUNT(*) FROM AFA270
    WHERE CASE_MNG_NO = #{CASE_MNG_NO}
    AND CASE_MNG_ODRNO = #{CASE_MNG_ODRNO}
