mapper.insert:
		/* Park.Seoung.Won */
		/* 문제행동발생보고서 등록 */


	           SELECT NVL(MAX(MNG_SN), 0) +1 AS MNG_SN
	           FROM AFA270
	           WHERE 1=1
	           AND CASE_MNG_NO = #{CASE_MNG_NO}
	           AND CASE_MNG_ODRNO = #{CASE_MNG_ODRNO}
	           AND WRT_YMD = TO_CHAR(SYSDATE, 'YYYYMMDD')
	           AND INCDNT_ACDNT_CL_SE_CD = #{INCDNT_ACDNT_CL_SE_CD}



    INSERT INTO AFA270 (
        CASE_MNG_NO                                        /* 사례관리번호 */
        , CASE_MNG_ODRNO                                   /* 사례관리차수 */
        , WRT_YMD                                          /* 작성일자 */
        , INCDNT_ACDNT_CL_SE_CD                            /* 사건사고분류코드 */
        , MNG_SN                                           /* 관리일련번호 */
        , OCRN_DT                                          /* 발생일시 */
        , INCDNT_ACDNT_CL_ETC_NM                           /* 사건사고분류기타명 */
        , PLACE_NM                                         /* 장소명 */
        , PROBM_CN_PRTCLR_MATTER_NM                        /* 문제내용특이사항명 */
        , SITTN_CN                                         /* 상황내용 */
        , ACTN_MATTER_DTL_CN                               /* 조치사항내용 */
        , ETC_MATTER_CN                                    /* 기타사항내용 */
        , PIC_NO                                           /* 보고자번호 */
        , TKCG_INST_NO                                     /* 담당기관번호 */
        , FRST_RGTR_ID                                     /* 최초등록아이디 */
        , FRST_REG_DT                                      /* 최초등록일시 */
        , LAST_MDFR_ID                                     /* 최종수정자아이디 */
    ) 
    VALUES (
        #{CASE_MNG_NO}
        , #{CASE_MNG_ODRNO}
        , TO_CHAR(SYSDATE,'YYYYMMDD')
        , #{INCDNT_ACDNT_CL_SE_CD}
        , #{MNG_SN}
        , TO_DATE(#{OCRN_DT}||#{OCRN_HR},'YYYYMMDDHH24MI')
        , #{INCDNT_ACDNT_CL_ETC_NM}
        , #{PLACE_NM}
        , #{PROBM_CN_PRTCLR_MATTER_NM}
        , #{SITTN_CN}
        , #{ACTN_MATTER_DTL_CN}
        , #{ETC_MATTER_CN}
        , #{PIC_NO}
        , #{TKCG_INST_NO}
        , #{FRST_RGTR_ID}
        , SYSDATE
        , #{LAST_MDFR_ID}
    )

mapper.update:

/* Park.Seoung.Won */
