    , ACTN_MATTER_DTL_CN = #{ACTN_MATTER_DTL_CN}                           /* 조치사항상세내용 */
    , ETC_MATTER_CN = #{ETC_MATTER_CN}                                     /* 기타사항내용 */
    , LAST_MDFR_ID = #{LAST_MDFR_ID}                                       /* 최종수정자아이디 */
    , LAST_MDFCN_DT = SYSDATE                                              /* 최종수정일시 */

WHERE 1=1
