    MNGR_IDNTY_YN = #{MNGR_IDNTY_YN}        /* 관리자승인 */
    , LAST_MDFR_ID = #{LAST_MDFR_ID}        /* 최종수정아이디 */                                                     
    , LAST_MDFCN_DT = SYSDATE               /* 최종수정일시 */                                                       

WHERE 1=1
AND CASE_MNG_NO = #{CASE_MNG_NO__origin}
AND CASE_MNG_ODRNO = #{CASE_MNG_ODRNO__origin}
AND MNG_SN = #{MNG_SN__origin}
AND WRT_YMD = #{WRT_YMD__origin}
AND INCDNT_ACDNT_CL_SE_CD = #{INCDNT_ACDNT_CL_SE_CD__origin}

mapper.select:
/* Park.Seoung.Won */ /* 심리평가보고서 목록 */ /* selectCaseinqList - Lee JunYeong */ T1.CASE_MNG_NO AS CASE_MNG_NO /* 사례관리번호 */ , T1.CASE_MNG_ODRNO AS CASE_MNG_ODRNO /* 사례관리차수 */ , DEC_B64(NVL(T3.FLNM_ENCPT, T2.TRPR_NM_ENCPT)) AS TRPR_NM /* 대상자명암호화 */ , T2.TRPR_BRTH_YMD AS TRPR_BRTH_YMD /* 대상자출생일자 */ , NVL(T3.SXDC_SE_CD, T2.SXDC_SE_CD) AS SXDC_SE_CD /* 대상자성별구분코드 */ , T1.YNGBGS_SE_NO AS YNGBGS_SE_NO /* 청소년구분번호 */ , DEC_B64(T5.FLNM_ENCPT) AS PIC_NM /* 담당자명암호화 */ , T6.INST_NM AS INST_NM /* 담당기관명 */ , T2.CASE_TRPR_TYPE_SE_CD AS CASE_TRPR_TYPE_SE_CD /* 사례대상자유형구분코드 */ , T1.CASE_PRGRS_STTS_SE_CD AS CASE_PRGRS_STTS_SE_CD /* 사례진행상태구분코드 */
, T1.CASE_BGNG_YMD AS CASE_BGNG_YMD /* 사례시작일자 */ , T1.CASE_TRMN_YMD AS CASE_TRMN_YMD /* 사례종결일자 */ , T11.TRMN_SE_CD AS TRMN_SE_CD /* 종결구분코드 */ , T11.TRMN_CS_SE_CD AS TRMN_CS_SE_CD /* 종결사유구분코드 */ , T10.BIZ_YR AS BIZ_YR /* 사업연도 */ , T9.SRVC_EXCN_BIZ_NO AS SRVC_EXCN_BIZ_NO /* 서비스실행사업번호 */ , T1.TRPR_INFO_NO AS TRPR_INFO_NO /* 대상자정보번호 */
FROM SEB100 T1 /* 사례기본 */ JOIN SEA200 T2 /* 대상자정보 */ ON T1.TRPR_INFO_NO = T2.TRPR_INFO_NO LEFT JOIN SCA300 T3 /* 개인정보 */ ON T2.INDV_IDNTFC_NO = T3.INDV_IDNTFC_NO LEFT JOIN SEB150 T4 /* 사례담당자 */ ON T1.CASE_MNG_NO = T4.CASE_MNG_NO AND T1.CASE_MNG_ODRNO = T4.CASE_MNG_ODRNO AND T4.PCHPRS_YN = 'Y' INNER JOIN SCA100 T5 /* 종사자 */ ON T4.CASE_PIC_NO = T5.ENFSN_NO LEFT JOIN SAA000 T6 /* 통합기관 */ ON T4.PIC_INST_NO = T6.INST_NO INNER JOIN SEB120 T8 /* 서비스사업대상자 */ ON T1.CASE_MNG_NO = T8.CASE_MNG_NO AND T1.CASE_MNG_ODRNO = T8.CASE_MNG_ODRNO AND T8.DEL_YN != 'Y' INNER JOIN SDA420 T9 /* 서비스실행사업 */ ON T8.SRVC_EXCN_BIZ_NO = T9.SRVC_EXCN_BIZ_NO LEFT JOIN SDA400 T10 /* 서비스사업 */ ON T9.SRVC_BIZ_NO = T10.SRVC_BIZ_NO LEFT JOIN (SELECT B.* ,ROW_NUMBER() OVER(PARTITION BY B.CASE_MNG_NO, B.CASE_MNG_ODRNO ORDER BY B.CASE_TRMN_NO DESC) AS RN FROM SEC100 A LEFT JOIN SEC100 B ON B.CASE_MNG_NO = A.CASE_MNG_NO AND B.CASE_MNG_NO = A.CASE_MNG_NO AND B.TRMN_SRNG_RESULT_SE_CD = '01' WHERE A.TRMN_SRNG_RESULT_SE_CD = '02' )T11 /* 사례종결 */ ON T11.CASE_MNG_NO = T1.CASE_MNG_NO AND T11.CASE_MNG_ODRNO = T1.CASE_MNG_ODRNO AND T11.RN=1
WHERE 1=1 AND T1.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD} AND (T9.INST_NO = #{INST_NO} OR #{INST_TYPE_SE_CD} < '5' OR #{AUTHRT_SE_CD} = '3300706' OR SUBSTR(#{AUTHRT_SE_CD},2,2) = '10') /* 사업연도 */ AND T10.BIZ_YR = #{BIZ_YR}
/* 대상자성명 */ AND NVL(T3.FLNM_ENCPT, T2.TRPR_NM_ENCPT) = ENC_B64(#{TRPR_NM})
/* 담당자성명 */ AND T5.FLNM_ENCPT = ENC_B64(#{PIC_NM})
/* 사례진행상태구분코드 */ AND T1.CASE_PRGRS_STTS_SE_CD LIKE #{CASE_PRGRS_STTS_SE_CD}
/* 서비스실행사업번호 */ AND T9.SRVC_EXCN_BIZ_NO LIKE #{SRVC_EXCN_BIZ_NO}
/* 사례대상자유형구분코드 */ AND T2.CASE_TRPR_TYPE_SE_CD LIKE #{CASE_TRPR_TYPE_SE_CD}
/* 청소년구분 */ AND T1.YNGBGS_SE_NO LIKE '%' || #{YNGBGS_STTS_LCLAS_SE_CD} || '%'
/* 배정그룹구분코드 */ AND T1.ALTMNT_GROUP_SCLAS_SE_CD LIKE #{ALTMNT_GROUP_SCLAS_SE_CD}
/* 종결구분코드 */ AND T11.TRMN_SE_CD LIKE #{TRMN_SE_CD}
ORDER BY CASE_MNG_NO, CASE_MNG_ODRNO


SELECT TRPR_PHOTO_ATFINO AS ATFINO FROM AFA100
WHERE  TRPR_INFO_NO = #{TRPR_INFO_NO}
   AND APLY_RCPT_SN = #{APLY_RCPT_SN}

mapper.insert:
/* insertPtcptReqstdAplcntPopHstr (대상자문제상태내역 이력) - Lee Hye Sun */
INSERT INTO AFA121 (
      TRPR_INFO_NO                         --대상자정보번호
    , APLY_RCPT_SN                         --신청접수일련번호
    , CASE_MNG_NO                          --사례관리번호
    , CASE_MNG_ODRNO                       --사례관리차수
    , MDFCN_DT                             --수정일시
    , INTLGN_INSP_RESULT_NM                --지능검사결과명
    , INSP_TYPE_NM                         --검사유형명
    , INSP_RESULT_SCORE                    --지능검사결과점수
    , INSP_ENFORC_YMD                      --지능검사실시일
    , VIOLNC_INCLN_SE_CD                   --폭력성향구분코드
    , SLFIJR_CTPV_YN_SE_CD                 --자해시도여부구분코드
    , SLFIJR_CTPV_CONT                     --자해시도횟수
    , SLFIJR_CTPV_ETC_NM                   --자해시도기타명(자해내용)
    , SUCDE_CTPV_YN_SE_CD                  --자살시도여부구분코드
    , SUCDE_CTPV_CONT                      --자살시도횟수
    , SUCDE_CTPV_ETC_NM                    --자살시도기타명
    , PTCPTN_MTVTN_SCORE                   --참여동기점수
    , BRHS_LVING_ADAPT_SE_CD               --기숙사생활적응구분코드
    , BRHS_LVING_MALADJ_CS_CN              --기숙사생활부적응사유내용
    , NOW_TAKNG_DRFSTF_YN_SE_CD            --현재복용약물여부구분코드
    , NOW_TAKNG_PRD_NM                     --현재복용기간명
    , NOW_TAKNG_DRFSTF_NM                  --현재복용약물명
    , HSPTL_MECE_YN_SE_CD                  --병원진단서여부구분코드
    , HSPTL_DGNSS_NM                       --병원진단명
    , LGSLTN_PROBM_PRD_NM                  --법률문제기간명
    , LGSLTN_PROBM_CN                      --법률문제내용
    , DSCSN_PRD_NM                         --상담기간명
    , DSCSN_CONT                           --상담횟수
    , TTM_APEAL_PROBM_CN                   --당시호소문제내용
    , RPRS_MAAP_PROBM_SE_CD                --대표주호소문제구분코드
    , RQST_CS_CN                           --의뢰사유내용
    , RQST_INST_MDLRT_GOAL_CN              --의뢰기관치료목표내용
    , NOW_NEED_HELP_CN                     --현재필요도움내용
    , PEHI_CN                              --개인력내용
    , FAM_ENVRN_GROWTH_CN                  --가족환경성장내용
    , SOCTY_REL_DEVLPA_HSTR_CN             --사회발달이력내용
    , PROBM_GHVR_CHC_PRVSON_DTL_DSCRP_CN   --문제행동선택항목상세설명내용
    , COMPNO_CHC_TYPE_MNG_NO               --복수선택유형관리번호
    , FRST_RGTR_ID
    , FRST_REG_DT
    , LAST_MDFR_ID
    , LAST_MDFCN_DT
) VALUES (
      #{TRPR_INFO_NO}                   
    , #{APLY_RCPT_SN}
    , #{CASE_MNG_NO}
    , #{CASE_MNG_ODRNO}         
    , SYSDATE  
    , #{INTLGN_INSP_RESULT_NM} 
    , #{INSP_TYPE_NM}                
    , #{INSP_RESULT_SCORE}   
    , #{INSP_ENFORC_YMD}               
    , #{VIOLNC_INCLN_SE_CD}    
    , #{SLFIJR_CTPV_YN_SE_CD}     
    , #{SLFIJR_CTPV_CONT}              
    , #{SLFIJR_CTPV_ETC_NM}        
    , #{SUCDE_CTPV_YN_SE_CD}   
    , #{SUCDE_CTPV_CONT}            
    , #{SUCDE_CTPV_ETC_NM}      
    , #{PTCPTN_MTVTN_SCORE}     
    , #{BRHS_LVING_ADAPT_SE_CD} 
    , #{BRHS_LVING_MALADJ_CS_CN}   
    , #{NOW_TAKNG_DRFSTF_YN_SE_CD}
    , #{NOW_TAKNG_PRD_NM}           
    , #{NOW_TAKNG_DRFSTF_NM}   
    , #{HSPTL_MECE_YN_SE_CD}   
    , #{HSPTL_DGNSS_NM}        
    , #{LGSLTN_PROBM_PRD_NM}   
    , #{LGSLTN_PROBM_CN}       
    , #{DSCSN_PRD_NM}          
    , #{DSCSN_CONT}            
    , #{TTM_APEAL_PROBM_CN}    
    , #{RPRS_MAAP_PROBM_SE_CD} 
    , #{RQST_CS_CN}            
    , #{RQST_INST_MDLRT_GOAL_CN}
    , #{NOW_NEED_HELP_CN}       
    , #{PEHI_CN}                
    , #{FAM_ENVRN_GROWTH_CN}    
    , #{SOCTY_REL_DEVLPA_HSTR_CN} 
    , #{PROBM_GHVR_CHC_PRVSON_DTL_DSCRP_CN} 
    , #{COMPNO_CHC_TYPE_MNG_NO}
    , #{FRST_RGTR_ID}
    , SYSDATE
    , #{LAST_MDFR_ID}
    , SYSDATE
)
